-- CA-001C production commands. All mutations reauthorize the supplied actor.
alter table public.onboarding_cases drop constraint onboarding_cases_status_check;
alter table public.onboarding_cases add constraint onboarding_cases_status_check check(status in('pending','ready','in_progress','customer_action_required','internal_action_required','blocked','suspended','expired','ready_for_provisioning','provisioning','ready_for_handoff','completed','cancelled'));
create table public.onboarding_provisioning_attempts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,onboarding_case_id uuid not null references public.onboarding_cases(id),customer_account_id uuid not null,product_family text not null check(product_family in('hpm','guidebook_studio','furnishing','investment_intelligence')),idempotency_key_hash text not null,status text not null check(status in('claimed','completed','retryable_failure','cancelled')),context_type text,context_id uuid,first_value_reference_id text,stable_failure_code text,attempt_count integer not null default 1,correlation_id text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(onboarding_case_id,product_family),unique(idempotency_key_hash),foreign key(customer_account_id,tenant_id)references public.customer_accounts(id,tenant_id));
alter table public.onboarding_provisioning_attempts enable row level security;create policy "admins read onboarding provisioning attempts"on public.onboarding_provisioning_attempts for select to authenticated using(public.is_admin());revoke all on public.onboarding_provisioning_attempts from anon;revoke insert,update,delete on public.onboarding_provisioning_attempts from authenticated;grant select on public.onboarding_provisioning_attempts to authenticated;
create function public.create_onboarding_plan(p_actor_id uuid,p_case jsonb,p_modules jsonb,p_templates jsonb,p_idempotency_hash text,p_correlation_id text)
returns public.onboarding_cases language plpgsql security definer set search_path='' as $$
declare v_case public.onboarding_cases;v_allowed boolean;
begin
 select exists(select 1 from public.profiles p where p.id=p_actor_id and p.role='admin')or exists(select 1 from public.customer_account_memberships m where m.profile_id=p_actor_id and m.tenant_id=(p_case->>'tenantId')::uuid and m.customer_account_id=(p_case->>'customerAccountId')::uuid and m.status='active')into v_allowed;
 if not v_allowed then raise exception'ONBOARDING_NOT_AUTHORIZED';end if;
 select * into v_case from public.onboarding_cases where source_type=p_case->>'sourceType'and source_reference_id=p_case->>'sourceReferenceId';if found then return v_case;end if;
 insert into public.onboarding_cases(id,tenant_id,customer_account_id,source_type,source_reference_id,status,plan_version,current_module_instance_id,idempotency_key_hash,created_at,updated_at,revision)
 values((p_case->>'id')::uuid,(p_case->>'tenantId')::uuid,(p_case->>'customerAccountId')::uuid,p_case->>'sourceType',p_case->>'sourceReferenceId',p_case->>'status',(p_case->>'planVersion')::integer,nullif(p_case->>'currentModuleInstanceId','')::uuid,p_idempotency_hash,(p_case->>'createdAt')::timestamptz,(p_case->>'updatedAt')::timestamptz,(p_case->>'revision')::integer)returning*into v_case;
 insert into public.onboarding_module_instances(id,onboarding_case_id,tenant_id,module_code,module_version,product_family,status,responsibility,required,sequence,reused_from_module_instance_id,verified_at,completed_at,revision)
 select x.id,v_case.id,v_case.tenant_id,x.module_code,x.module_version,x.product_family,x.status,x.responsibility,x.required,x.sequence,x.reused_from,x.verified_at,x.completed_at,x.revision from jsonb_to_recordset(p_modules)as x(id uuid,module_code text,module_version integer,product_family text,status text,responsibility text,required boolean,sequence integer,reused_from uuid,verified_at timestamptz,completed_at timestamptz,revision integer);
 insert into public.onboarding_plan_templates(tenant_id,onboarding_case_id,template_code,template_version)select v_case.tenant_id,v_case.id,x.code,x.version from jsonb_to_recordset(p_templates)as x(code text,version integer);
 insert into public.onboarding_audit_events(tenant_id,onboarding_case_id,event_type,actor_id,actor_type,correlation_id,idempotency_key_hash)values(v_case.tenant_id,v_case.id,'onboarding_plan_assembled',p_actor_id,case when exists(select 1 from public.profiles where id=p_actor_id and role='admin')then'internal'else'customer'end,p_correlation_id,p_idempotency_hash);
 return v_case;
end$$;

create function public.save_onboarding_draft(p_actor_id uuid,p_submission jsonb,p_expected_revision integer,p_idempotency_hash text,p_correlation_id text)
returns public.onboarding_submissions language plpgsql security definer set search_path='' as $$
declare v_module public.onboarding_module_instances;v_case public.onboarding_cases;v_submission public.onboarding_submissions;
begin
 select * into v_module from public.onboarding_module_instances where id=(p_submission->>'moduleInstanceId')::uuid for update;if not found or v_module.revision<>p_expected_revision then raise exception'STALE_ONBOARDING_REVISION';end if;
 select * into v_case from public.onboarding_cases where id=v_module.onboarding_case_id;
 if not exists(select 1 from public.customer_account_memberships m where m.profile_id=p_actor_id and m.tenant_id=v_case.tenant_id and m.customer_account_id=v_case.customer_account_id and m.status='active')then raise exception'ONBOARDING_NOT_AUTHORIZED';end if;
 select * into v_submission from public.onboarding_submissions where module_instance_id=v_module.id and revision=(p_submission->>'revision')::integer;if found then return v_submission;end if;
 insert into public.onboarding_submissions(id,tenant_id,onboarding_case_id,module_instance_id,schema_code,schema_version,submitted_by,submitted_at,data_classification,validation_status,validated_data,revision)values((p_submission->>'id')::uuid,v_case.tenant_id,v_case.id,v_module.id,p_submission->>'schemaCode',(p_submission->>'schemaVersion')::integer,p_actor_id,(p_submission->>'submittedAt')::timestamptz,p_submission->>'dataClassification',p_submission->>'validationStatus',p_submission->'validatedData',(p_submission->>'revision')::integer)returning*into v_submission;
 update public.onboarding_module_instances set revision=revision+1 where id=v_module.id;
 insert into public.onboarding_audit_events(tenant_id,onboarding_case_id,module_instance_id,event_type,actor_id,actor_type,correlation_id,idempotency_key_hash)values(v_case.tenant_id,v_case.id,v_module.id,'onboarding_module_draft_saved',p_actor_id,'customer',p_correlation_id,p_idempotency_hash);
 return v_submission;
end$$;

create function public.transition_onboarding_module(p_actor_id uuid,p_module_id uuid,p_to_status text,p_expected_revision integer,p_reason_code text,p_customer_safe_message text,p_correlation_id text)
returns public.onboarding_module_instances language plpgsql security definer set search_path='' as $$
declare v_module public.onboarding_module_instances;v_case public.onboarding_cases;v_internal boolean;v_member boolean;
begin
 select * into v_module from public.onboarding_module_instances where id=p_module_id for update;if not found or v_module.revision<>p_expected_revision then raise exception'STALE_ONBOARDING_REVISION';end if;select * into v_case from public.onboarding_cases where id=v_module.onboarding_case_id;
 select exists(select 1 from public.profiles where id=p_actor_id and role='admin')into v_internal;select exists(select 1 from public.customer_account_memberships where profile_id=p_actor_id and tenant_id=v_case.tenant_id and customer_account_id=v_case.customer_account_id and status='active')into v_member;
 if not v_internal and not v_member then raise exception'ONBOARDING_NOT_AUTHORIZED';end if;if p_to_status in('verified','changes_requested')and not v_internal then raise exception'ONBOARDING_REVIEW_NOT_AUTHORIZED';end if;if p_to_status='submitted'and not v_member then raise exception'ONBOARDING_SUBMIT_NOT_AUTHORIZED';end if;
 update public.onboarding_module_instances set status=p_to_status,submitted_at=case when p_to_status='submitted'then now()else submitted_at end,verified_at=case when p_to_status='verified'then now()else verified_at end,completed_at=case when p_to_status in('verified','skipped')then now()else completed_at end,revision=revision+1 where id=p_module_id returning*into v_module;
 insert into public.onboarding_audit_events(tenant_id,onboarding_case_id,module_instance_id,event_type,actor_id,actor_type,reason_code,customer_safe_message,correlation_id)values(v_case.tenant_id,v_case.id,v_module.id,case p_to_status when'submitted'then'onboarding_module_submitted'when'verified'then'onboarding_module_verified'else'onboarding_module_changes_requested'end,p_actor_id,case when v_internal then'internal'else'customer'end,p_reason_code,p_customer_safe_message,p_correlation_id);
 return v_module;
end$$;
create function public.unlock_onboarding_module(p_actor_id uuid,p_module_id uuid,p_expected_revision integer,p_correlation_id text)
returns public.onboarding_module_instances language plpgsql security definer set search_path='' as $$
declare v_module public.onboarding_module_instances;v_case public.onboarding_cases;begin select*into v_module from public.onboarding_module_instances where id=p_module_id for update;if not found or v_module.revision<>p_expected_revision or v_module.status<>'locked'then raise exception'ONBOARDING_UNLOCK_CONFLICT';end if;select*into v_case from public.onboarding_cases where id=v_module.onboarding_case_id;if not exists(select 1 from public.profiles where id=p_actor_id and role='admin')and not exists(select 1 from public.customer_account_memberships where profile_id=p_actor_id and tenant_id=v_case.tenant_id and customer_account_id=v_case.customer_account_id and status='active')then raise exception'ONBOARDING_NOT_AUTHORIZED';end if;update public.onboarding_module_instances set status='available',revision=revision+1 where id=p_module_id returning*into v_module;insert into public.onboarding_audit_events(tenant_id,onboarding_case_id,module_instance_id,event_type,actor_id,actor_type,correlation_id)values(v_case.tenant_id,v_case.id,v_module.id,'onboarding_module_available',p_actor_id,'system',p_correlation_id);return v_module;end$$;
create function public.transition_onboarding_case_lifecycle(p_actor_id uuid,p_case_id uuid,p_to_status text,p_expected_revision integer,p_reason_code text,p_correlation_id text)
returns public.onboarding_cases language plpgsql security definer set search_path=''as $$declare v_case public.onboarding_cases;v_internal boolean;begin select*into v_case from public.onboarding_cases where id=p_case_id for update;if not found or v_case.revision<>p_expected_revision then raise exception'STALE_ONBOARDING_REVISION';end if;select exists(select 1 from public.profiles where id=p_actor_id and role='admin')into v_internal;if not v_internal and not(p_to_status='in_progress'and v_case.status in('suspended','expired')and exists(select 1 from public.customer_account_memberships where profile_id=p_actor_id and tenant_id=v_case.tenant_id and customer_account_id=v_case.customer_account_id and status='active'))then raise exception'ONBOARDING_NOT_AUTHORIZED';end if;if p_to_status not in('suspended','expired','cancelled','in_progress')then raise exception'ONBOARDING_LIFECYCLE_INVALID';end if;update public.onboarding_cases set status=p_to_status,cancelled_at=case when p_to_status='cancelled'then now()else cancelled_at end,updated_at=now(),revision=revision+1 where id=p_case_id returning*into v_case;insert into public.onboarding_audit_events(tenant_id,onboarding_case_id,event_type,actor_id,actor_type,reason_code,correlation_id)values(v_case.tenant_id,v_case.id,case p_to_status when'suspended'then'onboarding_case_suspended'when'expired'then'onboarding_case_expired'when'cancelled'then'onboarding_case_cancelled'else'onboarding_case_restored'end,p_actor_id,case when v_internal then'internal'else'customer'end,p_reason_code,p_correlation_id);return v_case;end$$;
create function public.record_onboarding_provisioning_attempt(p_actor_id uuid,p_input jsonb,p_status text,p_result jsonb,p_failure_code text)
returns public.onboarding_provisioning_attempts language plpgsql security definer set search_path=''as $$declare v_case public.onboarding_cases;v_attempt public.onboarding_provisioning_attempts;begin select*into v_case from public.onboarding_cases where id=(p_input->>'onboardingCaseId')::uuid;if not found or v_case.tenant_id<>(p_input->>'tenantId')::uuid or v_case.customer_account_id<>(p_input->>'customerAccountId')::uuid then raise exception'ONBOARDING_NOT_AUTHORIZED';end if;if not exists(select 1 from public.profiles where id=p_actor_id and role='admin')and not exists(select 1 from public.customer_account_memberships where profile_id=p_actor_id and tenant_id=v_case.tenant_id and customer_account_id=v_case.customer_account_id and status='active')then raise exception'ONBOARDING_NOT_AUTHORIZED';end if;insert into public.onboarding_provisioning_attempts(tenant_id,onboarding_case_id,customer_account_id,product_family,idempotency_key_hash,status,context_type,context_id,first_value_reference_id,stable_failure_code,correlation_id)values(v_case.tenant_id,v_case.id,v_case.customer_account_id,p_input->>'productFamily',pg_catalog.encode(extensions.digest(p_input->>'idempotencyKey','sha256'),'hex'),p_status,p_result->>'contextType',nullif(p_result->>'contextId','')::uuid,p_result->>'firstValueReferenceId',p_failure_code,p_input->>'correlationId')on conflict(onboarding_case_id,product_family)do update set status=excluded.status,context_type=coalesce(excluded.context_type,public.onboarding_provisioning_attempts.context_type),context_id=coalesce(excluded.context_id,public.onboarding_provisioning_attempts.context_id),first_value_reference_id=coalesce(excluded.first_value_reference_id,public.onboarding_provisioning_attempts.first_value_reference_id),stable_failure_code=excluded.stable_failure_code,attempt_count=case when excluded.status='claimed'then public.onboarding_provisioning_attempts.attempt_count+1 else public.onboarding_provisioning_attempts.attempt_count end,updated_at=now()returning*into v_attempt;return v_attempt;end$$;
revoke all on function public.create_onboarding_plan(uuid,jsonb,jsonb,jsonb,text,text),public.save_onboarding_draft(uuid,jsonb,integer,text,text),public.transition_onboarding_module(uuid,uuid,text,integer,text,text,text),public.unlock_onboarding_module(uuid,uuid,integer,text),public.transition_onboarding_case_lifecycle(uuid,uuid,text,integer,text,text),public.record_onboarding_provisioning_attempt(uuid,jsonb,text,jsonb,text)from public,anon,authenticated;
